// Regenerates test/fixtures/mocks.ts from Mocks.sol (needs foundry on PATH).
//   node packages/relayer/test/fixtures/build-mocks.mjs
import { execFileSync } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const here = import.meta.dirname;
const tmp = mkdtempSync(join(tmpdir(), "cobra-mocks-"));
try {
  mkdirSync(join(tmp, "src"));
  copyFileSync(join(here, "Mocks.sol"), join(tmp, "src", "Mocks.sol"));
  writeFileSync(
    join(tmp, "foundry.toml"),
    '[profile.default]\nsrc = "src"\nout = "out"\nsolc_version = "0.8.28"\nevm_version = "cancun"\noptimizer = true\n',
  );
  execFileSync("forge", ["build", "--quiet"], { cwd: tmp, stdio: "inherit" });
  const pick = (n) => JSON.parse(readFileSync(join(tmp, "out", "Mocks.sol", `${n}.json`), "utf8")).bytecode.object;
  writeFileSync(
    join(here, "mocks.ts"),
    "// GENERATED by build-mocks.mjs from Mocks.sol — do not edit.\n" +
      `export const MOCK_ROUTER_BYTECODE = "${pick("MockRouter")}" as const;\n` +
      `export const MOCK_EIP3009_TOKEN_BYTECODE = "${pick("MockEip3009Token")}" as const;\n`,
  );
  console.log("wrote mocks.ts");
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
